def plot(output):
    sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "scripts"))
    from plot_cache_chiplets import make_figure

    data = {}
    for (query, size), rows in TIMELINE.items():
        array = np.asarray(rows, dtype=float).reshape(size, BINS, 8)
        data.setdefault(query, {})[size] = {
            "mpki": array[:, :, 0],
            "shares": array[:, :, 1:].transpose(0, 2, 1),
            "stats": {"dop": DOP[size]},
        }
    save_pdf(make_figure(data, sorted(data)), output, "cache_timeline_4c_8c")


if __name__ == "__main__":
    run_figure(plot, __doc__)
